diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -438,6 +438,23 @@
     }

     /* we now decrypt the encoded binary private dictionary */
+
+    /* Merged PFB segments keep a one-byte pad when `single_block' is */
+    /* set; otherwise an odd length is padded here.                   */
+    if ( parser->in_pfb && parser->single_block )
+      parser->private_len++;
+    else if ( parser->in_pfb && ( parser->private_len & 1 ) )
+    {
+      if ( FT_REALLOC( parser->private_dict,
+                       parser->private_len,
+                       parser->private_len + 1 ) )
+        goto Fail;
+
+      parser->private_dict[parser->private_len] = '\0';
+      parser->private_len++;
+      parser->single_block = 1;
+    }
+
     psaux->t1_decrypt( parser->private_dict, parser->private_len, 55665U );

     if ( parser->private_len < 4 )

